import { QuartzComponent, QuartzComponentConstructor, QuartzComponentProps } from "./types"
import { joinSegments, pathToRoot } from "../util/path"
import style from "./styles/markdownSource.scss"

/**
 * "Download as Markdown" row (Raúl 20.11.26): every page of the site has a
 * plain-markdown twin at /static/llm/<slug>.md, generated by the LlmMarkdown
 * emitter, and the whole site is indexed in /llms.txt for AI agents.
 */
const MarkdownSource: QuartzComponent = ({ fileData, displayClass }: QuartzComponentProps) => {
  const slug = fileData.slug
  if (!slug) return null
  const base = pathToRoot(slug)
  const mdHref = joinSegments(base, "static/llm", `${slug}.md`)
  const llmsHref = joinSegments(base, "llms.txt")
  const fileName = `${slug.split("/").pop() ?? "page"}.md`

  return (
    <div class={`ra-md-source ${displayClass ?? ""}`}>
      <a class="ra-md-chip" href={mdHref} download={fileName} data-no-popover="true">
        <span class="ra-md-chip-icon">⬇</span> Markdown
      </a>
      <span class="ra-md-hint">
        Plain-text copy of this page, free to download ·{" "}
        <a href={llmsHref} data-no-popover="true">
          llms.txt
        </a>{" "}
        for AI agents
      </span>
    </div>
  )
}

MarkdownSource.css = style
export default (() => MarkdownSource) satisfies QuartzComponentConstructor
